export const aliases:Record<string,string>={"Жим штанги лёжа":"Barbell_Bench_Press_-_Medium_Grip","Жим гантелей под углом 30°":"Incline_Dumbbell_Press","Тяга верхнего блока":"Close-Grip_Front_Lat_Pulldown","Горизонтальная тяга блока":"Seated_Cable_Rows","Сведение рук в кроссовере":"Cable_Crossover","Разведение гантелей в стороны":"Side_Lateral_Raise","Разгибание рук с канатом":"Triceps_Pushdown_-_Rope_Attachment","Разгибание рук из-за головы":"Cable_Rope_Overhead_Triceps_Extension","Подъём гантелей на бицепс":"Dumbbell_Bicep_Curl","Жим ногами":"Leg_Press","Подтягивания или тяга верхнего блока":"Pullups","Тяга Т-грифа с упором грудью":"Lying_T-Bar_Row","Жим гантелей на наклонной скамье":"Incline_Dumbbell_Press","Жим гантелей сидя":"Dumbbell_Shoulder_Press","Обратная бабочка":"Reverse_Flyes","Подъём EZ-штанги на бицепс":"EZ-Bar_Curl","Молотки с гантелями":"Hammer_Curls","Разгибание рук на блоке":"Triceps_Pushdown","Сгибание ног сидя":"Seated_Leg_Curl","Приседания или гакк-приседания":"Barbell_Squat","Болгарские выпады":"Split_Squat_with_Dumbbells","Разгибание ног":"Leg_Extensions","Ягодичный мост":"Barbell_Hip_Thrust","Подъём на носки":"Standing_Calf_Raises","Скручивания на блоке":"Cable_Crunch","Подтягивания":"Pullups","Тяга гантели в наклоне":"One-Arm_Dumbbell_Row","Отжимания":"Pushups","Махи гантелями в стороны":"Side_Lateral_Raise","Сгибания рук с гантелями":"Dumbbell_Bicep_Curl","Молотки":"Hammer_Curls","Французский жим":"EZ-Bar_Skullcrusher","Приседания":"Barbell_Squat","Планка":"Plank","Скручивания":"Crunches"};
const normalize=(n:string)=>n.toLowerCase().replace(/ё/g,'е').trim().replace(/\s+/g,' ');
const index=new Map(database.map(x=>[normalize(x.name),x]));const ids=new Map(database.map(x=>[x.id,x]));export function lookup(n:string){return ids.get(aliases[n])||index.get(normalize(n))}
export function matchesExercise(n:string,q:string){const x=lookup(n);return normalize(n+' '+(x?.english||'')+' '+(x?.primary||'')+' '+(x?.equipment||'')).includes(normalize(q))}
